  "contradictory_card_ids": ["C28", "C22", "C32"],
  "prediction_basis_card_ids": ["C07", "C13", "C16", "C02", "C06", "C30", "C37", "C42"],
  "claims": [
    {
      "claim": "FK788, the closest aryloxyacetic acid fused-ring analog with human data, had a calculated oral bioavailability of 55% in healthy volunteers (C07), affirmatively supporting F >= 20% for this chemotype; its rat value of 9.6% (C28) is species-specific context and does not overturn the human result.",
      "card_ids": ["C07", "C28"]
    },
    {
      "claim": "Etodolac, an ionizable carboxylic acid with a hydrophobic fused-ring system, has human absolute oral bioavailability of 0.80 (C13) and estimated near 1 (C16, C02), showing that acidic fused-ring molecules can achieve high F.",
      "card_ids": ["C13", "C16", "C02"]
    },
    {
      "claim": "Fed-state evidence supports high F: KNI-272 capsule post-prandial F was 36.4% at 6.6 mg/kg (C06) and 22.06% at 4 mg/kg (C30), and propranolol food increased F from 0.27 to 0.46 (C37).",
      "card_ids": ["C06", "C30", "C37"]
    },
    {
      "claim": "New L3 record C42 shows cicaprost, a prostacyclin analog with an ether-acetic acid side chain, had oral AUC0-inf 422 pg·h/ml versus IV 409 pg·h/ml (~100% bioavailability) in humans, directly supporting high oral F for this structural class.",
      "card_ids": ["C42"]
    },
    {
      "claim": "Low values in L2 (FK788 rat 9.6% C28, KNI-272 fed syrup 15.7% C22, S-propranolol rat 12% C32) are species/formulation-specific and do not provide affirmative threshold-relevant evidence for F < 20% in the human fed oral context.",
      "card_ids": ["C28", "C22", "C32"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C39", "C40", "C41", "C42", "C43", "C44", "C45", "C46", "C47", "C48", "C49", "C50"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "No fed-state-specific F data for the exact aryloxyacetic acid fused-ring chemotype; fed records are from KNI-272 (peptidomimetic) and propranolol (basic beta-blocker).",
    "Permeability, solubility, and active-transport status of the query are not experimentally established; the negative logD prior is physicochemical only.",
    "Species for the query is not specified; if the target is rat, low rat F values for analogs (FK788 9.6%, S-propranolol 12%) would be more concerning.",
    "Dose and formulation effects on F for the query are unknown; L3 Cmax records without IV comparators do not quantify F."
  ],
  "decision_summary": "Predicted high (F >= 20%) because the most transferable human gold records—FK788 (55%), etodolac (80-100%), and fed KNI-272 (36.4%)—affirmatively support F >= 20%, and new L3 cicaprost AUC/IV comparison (~100% F) strengthens the prostacyclin-analog support. Low rat/syrup values are species/formulation-specific and do not overturn; the unfavorable logD prior is insufficient to predict low."
}

